using Dapper;
using Npgsql;
using Sigov.Application.Almoxarifado;

namespace Sigov.Infrastructure.Almoxarifado;

public sealed partial class AlmoxarifadoService
{
    public async Task<AlmoxarifadoPagina<TransferenciaDto>> ListarTransferenciasAsync(long tenantId,long entidadeId,string? status,int pagina,CancellationToken ct)
    {
        pagina=Math.Max(1,pagina); const int tamanho=25;
        await using var c=factory.CreateConnection();
        var args=new{T=tenantId,E=entidadeId,S=N(status),O=(pagina-1)*tamanho,L=tamanho};
        var total=await c.ExecuteScalarAsync<long>(new CommandDefinition("select count(*) from sigov.almoxarifado_transferencia where tenant_id=@T and entidade_id=@E and (@S is null or status=@S)",args,cancellationToken:ct));
        var headers=(await c.QueryAsync<TransferHeader>(new CommandDefinition(TransferHeaderSql+" and (@S is null or x.status=@S) order by x.created_at desc,x.id desc limit @L offset @O",args,cancellationToken:ct))).AsList();
        var ids=headers.Select(x=>x.Id).ToArray();
        var items=ids.Length==0?new List<TransferItemWithDocument>(): (await c.QueryAsync<TransferItemWithDocument>(new CommandDefinition(TransferItemSql+" and i.transferencia_id=any(@Ids) order by i.transferencia_id,i.id",new{T=tenantId,Ids=ids},cancellationToken:ct))).AsList();
        var rows=headers.Select(h=>Map(h,items.Where(x=>x.TransferenciaId==h.Id).Select(x=>x.Item).ToList())).ToList();
        return new(rows,pagina,tamanho,total);
    }

    public async Task<TransferenciaDto?> ObterTransferenciaAsync(long tenantId,long entidadeId,long id,CancellationToken ct)
    {await using var c=factory.CreateConnection();return await CarregarTransferencia(c,tenantId,entidadeId,id,ct);}

    public async Task<long> CriarTransferenciaAsync(long tenantId,long entidadeId,long? exercicioId,long usuarioId,string correlationId,TransferenciaInput input,CancellationToken ct)
    {
        if(input.OrigemId==input.DestinoId)throw new ArgumentException("Origem e destino devem ser diferentes.");
        if(string.IsNullOrWhiteSpace(input.Justificativa)||string.IsNullOrWhiteSpace(input.Responsavel))throw new ArgumentException("Justificativa e responsável são obrigatórios.");
        if(input.EsferaGoverno is not ("municipal" or "estadual" or "federal"))throw new ArgumentException("Esfera de governo inválida.");
        if(string.IsNullOrWhiteSpace(input.IdempotencyKey)||input.IdempotencyKey.Length>100)throw new ArgumentException("Chave de idempotência é obrigatória e deve ter até 100 caracteres.");
        if(input.Itens.Count==0||input.Itens.Any(x=>x.Quantidade<=0))throw new ArgumentException("Informe ao menos um item com quantidade maior que zero.");
        await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);
        var locais=await c.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from sigov.almoxarifado_local where tenant_id=@T and entidade_id=@E and id in(@O,@D) and ativo",new{T=tenantId,E=entidadeId,O=input.OrigemId,D=input.DestinoId},tx,cancellationToken:ct));
        if(locais!=2)throw new InvalidOperationException("Origem e destino devem ser almoxarifados ativos da entidade atual; transferências entre entidades não possuem regra de domínio nesta entrega.");
        var existente=await c.ExecuteScalarAsync<long?>(new CommandDefinition("select id from sigov.almoxarifado_transferencia where tenant_id=@T and entidade_id=@E and idempotency_key=@K",new{T=tenantId,E=entidadeId,K=input.IdempotencyKey},tx,cancellationToken:ct));if(existente is not null)return existente.Value;
        var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.almoxarifado_transferencia(tenant_id,entidade_id,exercicio_id,esfera_governo,almoxarifado_origem_id,almoxarifado_destino_id,status,justificativa,responsavel,idempotency_key,created_by) values(@T,@E,@X,@Esfera,@O,@D,'RASCUNHO',@J,@R,@K,@U) returning id",new{T=tenantId,E=entidadeId,X=exercicioId,Esfera=input.EsferaGoverno,O=input.OrigemId,D=input.DestinoId,J=input.Justificativa.Trim(),R=input.Responsavel.Trim(),K=input.IdempotencyKey,U=usuarioId},tx,cancellationToken:ct));
        foreach(var item in input.Itens){var valido=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.almoxarifado_material where tenant_id=@T and entidade_id=@E and id=@M and ativo)",new{T=tenantId,E=entidadeId,M=item.MaterialId},tx,cancellationToken:ct));if(!valido)throw new KeyNotFoundException("Material ativo não encontrado na entidade atual.");await c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_transferencia_item(tenant_id,transferencia_id,item_id,quantidade,lote,validade) values(@T,@Id,@M,@Q,@L,@V)",new{T=tenantId,Id=id,M=item.MaterialId,Q=item.Quantidade,L=N(item.Lote),V=item.Validade},tx,cancellationToken:ct));}
        await TransferEvent(c,tx,tenantId,entidadeId,id,"CRIADA",usuarioId,correlationId,new{input.Responsavel},ct);await tx.CommitAsync(ct);return id;
    }

    public async Task ExpedirTransferenciaAsync(long tenantId,long entidadeId,long usuarioId,string correlationId,long id,CancellationToken ct)
    {
        await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);
        var doc=await c.QuerySingleOrDefaultAsync<TransferRow>(new CommandDefinition("select id,status,almoxarifado_origem_id OrigemId from sigov.almoxarifado_transferencia where tenant_id=@T and entidade_id=@E and id=@Id for update",new{T=tenantId,E=entidadeId,Id=id},tx,cancellationToken:ct))??throw new KeyNotFoundException("Transferência não encontrada.");
        if(doc.Status!="RASCUNHO")throw new InvalidOperationException("Somente transferência em rascunho pode ser expedida.");
        var itens=(await c.QueryAsync<TransferItemRow>(new CommandDefinition("select id,item_id MaterialId,quantidade,lote,validade from sigov.almoxarifado_transferencia_item where tenant_id=@T and transferencia_id=@Id order by id for update",new{T=tenantId,Id=id},tx,cancellationToken:ct))).AsList();
        foreach(var item in itens){await c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_estoque(tenant_id,entidade_id,almoxarifado_id,material_id,quantidade) values(@T,@E,@L,@M,0) on conflict(tenant_id,entidade_id,almoxarifado_id,material_id) do nothing",new{T=tenantId,E=entidadeId,L=doc.OrigemId,M=item.MaterialId},tx,cancellationToken:ct));var antes=await c.ExecuteScalarAsync<decimal>(new CommandDefinition("select quantidade from sigov.almoxarifado_estoque where tenant_id=@T and entidade_id=@E and almoxarifado_id=@L and material_id=@M for update",new{T=tenantId,E=entidadeId,L=doc.OrigemId,M=item.MaterialId},tx,cancellationToken:ct));if(antes<item.Quantidade)throw new InvalidOperationException($"Saldo disponível insuficiente para o material {item.MaterialId}. Disponível: {antes}.");var depois=antes-item.Quantidade;await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_estoque set quantidade=@Q,updated_at=now() where tenant_id=@T and entidade_id=@E and almoxarifado_id=@L and material_id=@M",new{Q=depois,T=tenantId,E=entidadeId,L=doc.OrigemId,M=item.MaterialId},tx,cancellationToken:ct));var mov=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.almoxarifado_movimentacao(tenant_id,entidade_id,almoxarifado_id,material_id,tipo,motivo,quantidade,lote,validade,documento_origem,saldo_antes,saldo_depois,usuario_id,correlation_id) values(@T,@E,@L,@M,'SAIDA','TRANSFERENCIA',@Q,@Lote,@V,@Doc,@Antes,@Depois,@U,@C) returning id",new{T=tenantId,E=entidadeId,L=doc.OrigemId,M=item.MaterialId,Q=item.Quantidade,Lote=item.Lote,V=item.Validade,Doc=$"TRANSFERENCIA:{id}",Antes=antes,Depois=depois,U=usuarioId,C=correlationId},tx,cancellationToken:ct));await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_transferencia_item set movimento_saida_id=@Mov where id=@Item and tenant_id=@T",new{Mov=mov,Item=item.Id,T=tenantId},tx,cancellationToken:ct));}
        await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_transferencia set status='EM_TRANSITO',expedida_em=now(),expedida_por=@U where id=@Id and tenant_id=@T and entidade_id=@E",new{U=usuarioId,Id=id,T=tenantId,E=entidadeId},tx,cancellationToken:ct));await TransferEvent(c,tx,tenantId,entidadeId,id,"EXPEDIDA",usuarioId,correlationId,new{},ct);await tx.CommitAsync(ct);
    }

    public async Task ReceberTransferenciaAsync(long tenantId,long entidadeId,long usuarioId,string correlationId,long id,TransferenciaRecebimentoInput input,CancellationToken ct)
    {
        if(string.IsNullOrWhiteSpace(input.IdempotencyKey))throw new ArgumentException("Chave de idempotência é obrigatória.");
        await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);
        var doc=await c.QuerySingleOrDefaultAsync<TransferRow>(new CommandDefinition("select id,status,almoxarifado_destino_id DestinoId from sigov.almoxarifado_transferencia where tenant_id=@T and entidade_id=@E and id=@Id for update",new{T=tenantId,E=entidadeId,Id=id},tx,cancellationToken:ct))??throw new KeyNotFoundException("Transferência não encontrada.");
        if(await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.almoxarifado_transferencia_evento where tenant_id=@T and transferencia_id=@Id and idempotency_key=@K)",new{T=tenantId,Id=id,K=input.IdempotencyKey},tx,cancellationToken:ct)))return;
        if(doc.Status is not ("EM_TRANSITO" or "RECEBIDA_PARCIAL" or "DIVERGENCIA"))throw new InvalidOperationException("A transferência não está disponível para recebimento.");
        foreach(var recebido in input.Itens.Where(x=>x.QuantidadeRecebida>0||x.QuantidadeRecusada>0)){var item=await c.QuerySingleOrDefaultAsync<TransferItemRow>(new CommandDefinition("select id,item_id MaterialId,quantidade,quantidade_recebida QuantidadeRecebida,quantidade_recusada QuantidadeRecusada,lote,validade from sigov.almoxarifado_transferencia_item where tenant_id=@T and transferencia_id=@Id and id=@Item for update",new{T=tenantId,Id=id,Item=recebido.ItemId},tx,cancellationToken:ct))??throw new KeyNotFoundException("Item da transferência não encontrado.");if(recebido.QuantidadeRecebida<0||recebido.QuantidadeRecusada<0||item.QuantidadeRecebida+item.QuantidadeRecusada+recebido.QuantidadeRecebida+recebido.QuantidadeRecusada>item.Quantidade)throw new InvalidOperationException("Recebimento excede o saldo expedido pendente.");if(recebido.QuantidadeRecusada>0&&string.IsNullOrWhiteSpace(recebido.Divergencia))throw new ArgumentException("Informe o motivo da divergência para quantidade recusada.");if(recebido.QuantidadeRecebida>0){await c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_estoque(tenant_id,entidade_id,almoxarifado_id,material_id,quantidade) values(@T,@E,@L,@M,0) on conflict(tenant_id,entidade_id,almoxarifado_id,material_id) do nothing",new{T=tenantId,E=entidadeId,L=doc.DestinoId,M=item.MaterialId},tx,cancellationToken:ct));var antes=await c.ExecuteScalarAsync<decimal>(new CommandDefinition("select quantidade from sigov.almoxarifado_estoque where tenant_id=@T and entidade_id=@E and almoxarifado_id=@L and material_id=@M for update",new{T=tenantId,E=entidadeId,L=doc.DestinoId,M=item.MaterialId},tx,cancellationToken:ct));var depois=antes+recebido.QuantidadeRecebida;await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_estoque set quantidade=@Q,updated_at=now() where tenant_id=@T and entidade_id=@E and almoxarifado_id=@L and material_id=@M",new{Q=depois,T=tenantId,E=entidadeId,L=doc.DestinoId,M=item.MaterialId},tx,cancellationToken:ct));var mov=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.almoxarifado_movimentacao(tenant_id,entidade_id,almoxarifado_id,material_id,tipo,motivo,quantidade,lote,validade,documento_origem,observacao,saldo_antes,saldo_depois,usuario_id,correlation_id) values(@T,@E,@L,@M,'ENTRADA','TRANSFERENCIA',@Q,@Lote,@V,@Doc,@Obs,@Antes,@Depois,@U,@C) returning id",new{T=tenantId,E=entidadeId,L=doc.DestinoId,M=item.MaterialId,Q=recebido.QuantidadeRecebida,Lote=item.Lote,V=item.Validade,Doc=$"TRANSFERENCIA:{id}",Obs=N(input.Observacao),Antes=antes,Depois=depois,U=usuarioId,C=correlationId},tx,cancellationToken:ct));await c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_transferencia_recebimento(tenant_id,entidade_id,transferencia_id,item_id,quantidade,movimento_entrada_id,idempotency_key,usuario_id,correlation_id) values(@T,@E,@Id,@Item,@Q,@Mov,@K,@U,@C)",new{T=tenantId,E=entidadeId,Id=id,Item=item.Id,Q=recebido.QuantidadeRecebida,Mov=mov,K=input.IdempotencyKey,U=usuarioId,C=correlationId},tx,cancellationToken:ct));}await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_transferencia_item set quantidade_recebida=quantidade_recebida+@R,quantidade_recusada=quantidade_recusada+@X,divergencia=coalesce(@D,divergencia) where id=@Item and tenant_id=@T",new{R=recebido.QuantidadeRecebida,X=recebido.QuantidadeRecusada,D=N(recebido.Divergencia),Item=item.Id,T=tenantId},tx,cancellationToken:ct));}
        var saldo=await c.QuerySingleAsync<(decimal Total,decimal Recebida,decimal Recusada)>(new CommandDefinition("select sum(quantidade) Total,sum(quantidade_recebida) Recebida,sum(quantidade_recusada) Recusada from sigov.almoxarifado_transferencia_item where tenant_id=@T and transferencia_id=@Id",new{T=tenantId,Id=id},tx,cancellationToken:ct));var status=saldo.Recebida==saldo.Total?"RECEBIDA":saldo.Recusada>0?"DIVERGENCIA":"RECEBIDA_PARCIAL";await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_transferencia set status=@S,recebida_em=case when @S='RECEBIDA' then now() else recebida_em end,conferido_por=@U,conferido_em=now() where id=@Id and tenant_id=@T and entidade_id=@E",new{S=status,U=usuarioId,Id=id,T=tenantId,E=entidadeId},tx,cancellationToken:ct));await TransferEvent(c,tx,tenantId,entidadeId,id,"RECEBIMENTO",usuarioId,correlationId,new{status,input.Observacao},ct,input.IdempotencyKey);await tx.CommitAsync(ct);
    }

    const string TransferHeaderSql="select x.id,x.status,x.almoxarifado_origem_id OrigemId,o.nome OrigemNome,x.almoxarifado_destino_id DestinoId,d.nome DestinoNome,x.justificativa,x.responsavel,x.created_at CreatedAt,x.expedida_em ExpedidaEm,x.recebida_em RecebidaEm from sigov.almoxarifado_transferencia x join sigov.almoxarifado_local o on o.id=x.almoxarifado_origem_id and o.tenant_id=x.tenant_id join sigov.almoxarifado_local d on d.id=x.almoxarifado_destino_id and d.tenant_id=x.tenant_id where x.tenant_id=@T and x.entidade_id=@E";
    const string TransferItemSql="select i.transferencia_id TransferenciaId,i.id,i.item_id MaterialId,m.codigo,m.descricao,m.unidade_medida UnidadeMedida,i.quantidade,i.quantidade_recebida QuantidadeRecebida,i.quantidade_recusada QuantidadeRecusada,i.lote,i.divergencia from sigov.almoxarifado_transferencia_item i join sigov.almoxarifado_material m on m.id=i.item_id and m.tenant_id=i.tenant_id where i.tenant_id=@T";
    static async Task<TransferenciaDto?> CarregarTransferencia(NpgsqlConnection c,long t,long e,long id,CancellationToken ct){var h=await c.QuerySingleOrDefaultAsync<TransferHeader>(new CommandDefinition(TransferHeaderSql+" and x.id=@Id",new{T=t,E=e,Id=id},cancellationToken:ct));if(h is null)return null;var items=(await c.QueryAsync<TransferItemWithDocument>(new CommandDefinition(TransferItemSql+" and i.transferencia_id=@Id order by i.id",new{T=t,Id=id},cancellationToken:ct))).Select(x=>x.Item).ToList();return Map(h,items);}
    static TransferenciaDto Map(TransferHeader h,IReadOnlyList<TransferenciaItemDto> items)=>new(h.Id,h.Status,h.OrigemId,h.OrigemNome,h.DestinoId,h.DestinoNome,h.Justificativa,h.Responsavel,h.CreatedAt,h.ExpedidaEm,h.RecebidaEm,items);
    static async Task TransferEvent(NpgsqlConnection c,NpgsqlTransaction tx,long t,long e,long id,string tipo,long u,string corr,object dados,CancellationToken ct,string? key=null)=>await c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_transferencia_evento(tenant_id,entidade_id,transferencia_id,tipo,dados,usuario_id,correlation_id,idempotency_key) values(@T,@E,@Id,@Tipo,cast(@Dados as jsonb),@U,@C,@K)",new{T=t,E=e,Id=id,Tipo=tipo,Dados=System.Text.Json.JsonSerializer.Serialize(dados),U=u,C=corr,K=key},tx,cancellationToken:ct));
    sealed class TransferRow { public long Id {get;set;} public string Status {get;set;}=""; public long OrigemId {get;set;} public long DestinoId {get;set;} }
    sealed class TransferItemRow { public long Id {get;set;} public long MaterialId {get;set;} public decimal Quantidade {get;set;} public decimal QuantidadeRecebida {get;set;} public decimal QuantidadeRecusada {get;set;} public string? Lote {get;set;} public DateOnly? Validade {get;set;} }
    sealed class TransferHeader { public long Id {get;set;} public string Status {get;set;}=""; public long OrigemId {get;set;} public string OrigemNome {get;set;}=""; public long DestinoId {get;set;} public string DestinoNome {get;set;}=""; public string Justificativa {get;set;}=""; public string Responsavel {get;set;}=""; public DateTimeOffset CreatedAt {get;set;} public DateTimeOffset? ExpedidaEm {get;set;} public DateTimeOffset? RecebidaEm {get;set;} }
    sealed class TransferItemWithDocument { public long TransferenciaId {get;set;} public long Id {get;set;} public long MaterialId {get;set;} public string Codigo {get;set;}=""; public string Descricao {get;set;}=""; public string UnidadeMedida {get;set;}=""; public decimal Quantidade {get;set;} public decimal QuantidadeRecebida {get;set;} public decimal QuantidadeRecusada {get;set;} public string? Lote {get;set;} public string? Divergencia {get;set;} public TransferenciaItemDto Item=>new(Id,MaterialId,Codigo,Descricao,UnidadeMedida,Quantidade,QuantidadeRecebida,QuantidadeRecusada,Lote,Divergencia); }
}
